package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*;
import java.time.*; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.security.crypto.password.PasswordEncoder;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@SpringBootTest class LocalIdentityCreationConcurrencyIntegrationTest {
 @Autowired ClienteDAO clients; @Autowired AuthIdentityDAO identities; @Autowired ReauthenticationTokenDAO tokens; @Autowired LocalIdentityCreationService service; @Autowired PasswordEncoder passwords;
 UUID id; AuthenticatedUser user; String first; String second;
 @BeforeEach void setup(){Cliente c=clients.save(new Cliente("Race","Social","race-"+UUID.randomUUID()+"@test",null,"ROLE_CLIENTE",0,0,0,"","",""));id=c.getId();user=new AuthenticatedUser(id,c.getEmail(),Role.CLIENTE);identities.saveAndFlush(new AuthIdentity(id,Role.CLIENTE,AuthProvider.GOOGLE,"google-"+id,c.getEmail(),Instant.now()));first=token();second=token();}
 private String token(){String raw="reauth-"+UUID.randomUUID();tokens.saveAndFlush(new ReauthenticationToken(PasswordResetService.hash(raw),id,Role.CLIENTE,null,ReauthenticationPurpose.CREATE_LOCAL_IDENTITY,Instant.now(),Instant.now().plusSeconds(300)));return raw;}
 @Test void concurrentCreateLeavesOneLocalAndSafeConflict() throws Exception {CountDownLatch ready=new CountDownLatch(2),go=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);Future<String>a=pool.submit(()->attempt(first,ready,go)),b=pool.submit(()->attempt(second,ready,go));assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();List<String> results=List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));pool.shutdownNow();assertEquals(1,results.stream().filter("ok"::equals).count());assertEquals(1,results.stream().filter("conflict"::equals).count());List<AuthIdentity> local=identities.findByUserIdAndRoleAndActiveTrue(id,Role.CLIENTE).stream().filter(i->i.getProvider()==AuthProvider.LOCAL).toList();assertEquals(1,local.size());assertEquals(id.toString(),local.getFirst().getProviderSubject());assertTrue(local.getFirst().isActive());assertTrue(identities.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"google-"+id).orElseThrow().isActive());assertTrue(passwords.matches("ValidPassword123",clients.findById(id).orElseThrow().getContrasena()));long consumed=List.of(first,second).stream().map(raw->tokens.findAll().stream().filter(token->token.getTokenHash().equals(PasswordResetService.hash(raw))).findFirst().orElseThrow()).filter(token->token.getConsumedAt()!=null).count();assertEquals(1,consumed);}
 private String attempt(String raw,CountDownLatch ready,CountDownLatch go) throws Exception {ready.countDown();go.await(5,TimeUnit.SECONDS);try{service.create(user,new LocalIdentityCreationRequest(raw,"ValidPassword123"));return "ok";}catch(LocalIdentityAlreadyExistsException e){return "conflict";}}
}
